def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"SUM|MIN|MAX|IF|[A-Z][1-9][0-9]?|[0-9]+|"
        r"<>|<=|>=|[+\-*/(),:=<>]"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "u-": 3,
        ":": 4,
    }
    function_names = {"SUM", "MIN", "MAX", "IF"}

    def number(s):
        result = 0
        for start in range(0, len(s), 9):
            part = s[start:start + 9]
            result = result * (10 ** len(part)) + int(part)
        return result

    def parse(text):
        tokens = token_pattern.findall(text)
        operators = []
        operands = []
        argument_counts = []
        expecting_operand = True

        def apply_operator():
            op = operators.pop()
            if op == "u-":
                operands.append(("neg", operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                if op == ":":
                    operands.append(("range", left[1], right[1]))
                else:
                    operands.append(("binary", op, left, right))

        for token in tokens:
            if token in function_names:
                operators.append(token)
                expecting_operand = True
            elif token == "(":
                operators.append(token)
                argument_counts.append(1)
                expecting_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    apply_operator()
                argument_counts[-1] += 1
                expecting_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    apply_operator()
                operators.pop()
                count = argument_counts.pop()
                if operators and operators[-1] in function_names:
                    name = operators.pop()
                    args = operands[-count:]
                    del operands[-count:]
                    operands.append(("function", name, args))
                expecting_operand = False
            elif token in precedence:
                op = "u-" if token == "-" and expecting_operand else token
                while (
                    operators
                    and operators[-1] in precedence
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "u-"
                        )
                    )
                ):
                    apply_operator()
                operators.append(op)
                expecting_operand = True
            elif token[0].isdigit():
                operands.append(("number", number(token)))
                expecting_operand = False
            else:
                operands.append(("cell", token))
                expecting_operand = False

        while operators:
            apply_operator()
        return operands[0]

    def function_items(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue
            first, last = arg[1], arg[2]
            col1, col2 = sorted((ord(first[0]), ord(last[0])))
            row1, row2 = sorted((int(first[1:]), int(last[1:])))
            for row in range(row1, row2 + 1):
                for col in range(col1, col2 + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("cell", name)

    values = {}
    active = set()

    def evaluate(start):
        tasks = [("cell", start)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in values:
                    results.append(values[name])
                elif name not in cells:
                    results.append(0)
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name]
                    if content.startswith("="):
                        expression = parse(content[1:])
                        tasks.append(("finish_cell", name))
                        tasks.append(("eval", expression))
                    else:
                        if content.startswith("-"):
                            value = -number(content[1:])
                        elif content.startswith("+"):
                            value = number(content[1:])
                        else:
                            value = number(content)
                        active.remove(name)
                        values[name] = value
                        results.append(value)

            elif kind == "finish_cell":
                name = task[1]
                active.remove(name)
                values[name] = results[-1]

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]
                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "cell":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                else:
                    name, args = node[1], node[2]
                    if name == "IF":
                        tasks.append(("if", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        tasks.append(
                            ("aggregate_next", name, iter(function_items(args)), None)
                        )

            elif kind == "neg":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                else:
                    results.append(left >= right)

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate_next":
                name, items, accumulated = task[1], task[2], task[3]
                item = next(items, None)
                if item is None:
                    results.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append(("aggregate_value", name, items, accumulated))
                    tasks.append(("eval", item))

            else:  # aggregate_value
                name, items, accumulated = task[1], task[2], task[3]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if accumulated is None:
                        accumulated = value
                    elif name == "SUM":
                        accumulated += value
                    elif name == "MIN":
                        accumulated = min(accumulated, value)
                    else:
                        accumulated = max(accumulated, value)
                    tasks.append(("aggregate_next", name, items, accumulated))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
